#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    for (int k = 0; k < n; k++) {
        int sorted = 1;
        for (int i = 0; i < n - 1; i++) {
            int val1 = a[(i - k + n * 2) % n];
            int val2 = a[(i + 1 - k + n * 2) % n];
            if (val1 > val2) { sorted = 0; break; }
        }
        if (sorted) { printf("%d\n", k); free(a); return 0; }
    }
    puts("-1"); free(a);
    return 0;
}

