#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];
        for (int k = 0; k < n; k++) {
            bool sorted = true;
            for (int i = 0; i < n - 1; i++) {
                if (a[(i - k + 2 * n) % n] > a[(i + 1 - k + 2 * n) % n]) { sorted = false; break; }
            }
            if (sorted) { cout << k << "\n"; return 0; }
        }
        cout << "-1\n";
    }
    return 0;
}

